bool isAnagram(std::string s, std::string t) {
    if (s.length() != t.length()) return false;
    std::vector<int> freq(26, 0);
    for (char c : s) freq[c - 'a']++;
    for (char c : t) {
        freq[c - 'a']--;
        if (freq[c - 'a'] < 0) return false;
    }
    return true;
}

#include <vector>
bool isValid(const std::vector<int>& weights, int days, int max_cap) {
    int days_needed = 1, current_load = 0;
    for (int w : weights) {
        if (current_load + w > max_cap) {
            days_needed++;
            current_load = w;
        } else {
            current_load += w;
        }
    }
    return days_needed <= days;
}
int shipWithinDays(std::vector<int>& weights, int days) {
    int low = 0, high = 0;
    for (int w : weights) {
        low = std::max(low, w);
        high += w;
    }
    int ans = high;
    while (low <= high) { // Binary Search on Answer
        int mid = low + (high - low) / 2;
        if (isValid(weights, days, mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

