#include <vector>
class RangeSumQuery {
    std::vector<int> pref;
public:
    RangeSumQuery(std::vector<int>& arr) {
        int n = arr.size();
        pref.resize(n + 1, 0);
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + arr[i];
        }
    }
    int query(int L, int R) { // 0-indexed query
        return pref[R + 1] - pref[L];
    }
};

#include <string>
