int longestUniqueSubstring(std::string s) {
    std::vector<int> count(256, 0);
    int L = 0, R = 0, ans = 0, n = s.length();
    while (R < n) {
        count[s[R]]++;
        while (count[s[R]] > 1) { // Violates uniqueness constraint
            count[s[L]]--;
            L++; // Contract
        }
        ans = std::max(ans, R - L + 1); // Track maximum
        R++; // Expand
    }
    return ans;
}

