#include <vector>
std::vector<bool> sieve(int n) {
    std::vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= n; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= n; j += i) {
                is_prime[j] = false;
            }
        }
    }
    return is_prime;
}

// Fibonacci recursive split: F(n) = F(n-1) + F(n-2)
int fib(int n) {
    if (n <= 1) return n; // Base case
    return fib(n - 1) + fib(n - 2); // Recursive step
}

#include <vector>
#include <string>
void solve(int row, int n, std::vector<std::string>& board, std::vector<std::vector<std::string>>& ans,
           std::vector<bool>& cols, std::vector<bool>& diag1, std::vector<bool>& diag2) {
    if (row == n) {
        ans.push_back(board);
        return;
    }
    for (int col = 0; col < n; col++) {
        // Diagonal coordinate checks
        if (!cols[col] && !diag1[row + col] && !diag2[row - col + n - 1]) {
            board[row][col] = 'Q';
            cols[col] = diag1[row + col] = diag2[row - col + n - 1] = true;

            solve(row + 1, n, board, ans, cols, diag1, diag2); // Recurse

            board[row][col] = '.'; // Backtrack
            cols[col] = diag1[row + col] = diag2[row - col + n - 1] = false;
        }
    }
}

#include <vector>
bool hasPairSum(const std::vector<int>& arr, int target) {
    int L = 0, R = arr.size() - 1;
    while (L < R) {
        int current_sum = arr[L] + arr[R];
        if (current_sum == target) return true;
        if (current_sum < target) L++;
        else R--;
    }
    return false;
}

struct Node {
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr != nullptr) {
        Node* nextTemp = curr->next; // Save next node
        curr->next = prev;           // Reverse pointer
        prev = curr;                 // Move prev forward
        curr = nextTemp;             // Move curr forward
    }
    return prev;
}

#include <vector>
#include <stack>
std::vector<int> nextGreaterElement(const std::vector<int>& arr) {
    int n = arr.size();
    std::vector<int> ans(n, -1);
    std::stack<int> st; // Stores indices
    for (int i = 0; i < n; i++) {
        while (!st.empty() && arr[st.top()] < arr[i]) {
            ans[st.top()] = arr[i];
            st.pop();
        }
        st.push(i);
    }
    return ans;
}

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};
bool searchBST(TreeNode* root, int key) {
    if (root == nullptr) return false;
    if (root->val == key) return true;
    if (key < root->val) return searchBST(root->left, key);
    return searchBST(root->right, key);
}

#include <vector>
#include <queue>
std::vector<int> findKBest(const std::vector<int>& arr, int k) {
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap; // Min-Heap
    for (int x : arr) {
        minHeap.push(x);
        if (minHeap.size() > k) {
            minHeap.pop(); // Remove smallest
        }
    }
    std::vector<int> ans;
    while (!minHeap.empty()) {
        ans.push_back(minHeap.top());
        minHeap.pop();
    }
    return ans;
}

struct TrieNode {
    TrieNode* children[26];
    bool is_end_of_word;
    TrieNode() {
        is_end_of_word = false;
        for (int i = 0; i < 26; i++) children[i] = nullptr;
    }
};

class Trie {
    TrieNode* root;
public:
    Trie() { root = new TrieNode(); }

    void insert(std::string word) {
        TrieNode* curr = root;
        for (char c : word) {
            int idx = c - 'a';
            if (curr->children[idx] == nullptr) {
                curr->children[idx] = new TrieNode();
            }
            curr = curr->children[idx];
        }
        curr->is_end_of_word = true;
    }

    bool search(std::string word) {
        TrieNode* curr = root;
        for (char c : word) {
            int idx = c - 'a';
            if (curr->children[idx] == nullptr) return false;
            curr = curr->children[idx];
        }
        return curr->is_end_of_word;
    }
};

#include <vector>
#include <algorithm>
struct Meeting {
    int start, end;
};
bool compareMeetings(const Meeting& a, const Meeting& b) {
    return a.end < b.end; // Sort by earliest end time
}
int maxMeetings(std::vector<Meeting>& meetings) {
    std::sort(meetings.begin(), meetings.end(), compareMeetings);
    int count = 0, last_end = -1;
    for (const auto& m : meetings) {
        if (m.start >= last_end) {
            count++;
            last_end = m.end;
        }
    }
    return count;
}

#include <vector>
int knapsack(int W, const std::vector<int>& wt, const std::vector<int>& val) {
    int n = wt.size();
    // Space optimized: use 1D array of size W+1 instead of 2D table
    std::vector<int> dp(W + 1, 0);
    for (int i = 0; i < n; i++) {
        // Loop backwards to prevent using the same item multiple times
        for (int w = W; w >= wt[i]; w--) {
            dp[w] = std::max(dp[w], val[i] + dp[w - wt[i]]);
        }
    }
    return dp[W];
}

#include <vector>
#include <queue>
struct Edge { int to, weight; };
std::vector<int> dijkstra(int source, int n, const std::vector<std::vector<Edge>>& adj) {
    std::vector<int> dist(n, 1e9);
    dist[source] = 0;
    // Priority Queue stores {distance, node}
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
    pq.push({0, source});
    while (!pq.empty()) {
        int d = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (d > dist[u]) continue; // Stale update check
        for (const auto& edge : adj[u]) {
            if (dist[u] + edge.weight < dist[edge.to]) { // Relaxation
                dist[edge.to] = dist[u] + edge.weight;
                pq.push({dist[edge.to], edge.to});
            }
        }
    }
    return dist;
}

#include <vector>
class SegmentTree {
    int n;
    std::vector<int> tree;
    void build(const std::vector<int>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
            return;
        }
        int mid = start + (end - start) / 2;
        build(arr, 2 * node, start, mid);
        build(arr, 2 * node + 1, mid + 1, end);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
public:
    SegmentTree(const std::vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n, 0); // 4N allocation rule
        build(arr, 1, 0, n - 1);
    }
    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0; // Out of range
        if (l <= start && end <= r) return tree[node]; // Completely inside
        int mid = start + (end - start) / 2;
        return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
    }
};

